import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const o="/assets/1.B3sPKxj1.JPG",n="/assets/4.BdZrDkr3.JPG",s="/assets/image%20(3)%20(1)%20(1).DE7cSHPw.png",l="/assets/tradejini2%20(1).CoqZQSaS.PNG",d="/assets/tradejini3.DxOD0aYC.PNG",m=JSON.parse('{"title":"Tradejini","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/tradejini.md","filePath":"connect-brokers/brokers/tradejini.md"}'),c={name:"connect-brokers/brokers/tradejini.md"};function p(h,e,g,u,f,b){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="tradejini" tabindex="-1">Tradejini <a class="header-anchor" href="#tradejini" aria-label="Permalink to &quot;Tradejini&quot;">​</a></h1><p>TradeJini is a progressive brokerage firm known for its reliable execution, low-cost trading, and developer-friendly CubePlus API platform. Designed to support modern algo trading systems, TradeJini provides a robust infrastructure for both retail and institutional traders. Whether you&#39;re an individual trader or building advanced trading automation, TradeJini offers the right tools to seamlessly integrate market data and trading functionalities.</p><h3 id="steps-for-integration" tabindex="-1">Steps for Integration: <a class="header-anchor" href="#steps-for-integration" aria-label="Permalink to &quot;Steps for Integration:&quot;">​</a></h3><h4 id="_1-log-in-to-the-tradejini-developer-portal" tabindex="-1">1. Log in to the TradeJini Developer Portal <a class="header-anchor" href="#_1-log-in-to-the-tradejini-developer-portal" aria-label="Permalink to &quot;1. Log in to the TradeJini Developer Portal&quot;">​</a></h4><p>Start by accessing the CubePlus Developer Portal at<br><a href="https://api.tradejini.com/developer-portal/main" target="_blank" rel="noreferrer">https://api.tradejini.com/developer-portal/main</a></p><figure><img src="'+o+'" alt=""><figcaption></figcaption></figure><ul><li><p>Click on <strong>Login</strong>.</p></li><li><p>You can log in using either:</p><ul><li>Your <strong>email address and password</strong>, or</li><li>By clicking the <strong>TradeJini</strong> logo for broker login.</li></ul><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure></li></ul><h4 id="_2-create-a-new-app" tabindex="-1">2. Create a New App <a class="header-anchor" href="#_2-create-a-new-app" aria-label="Permalink to &quot;2. Create a New App&quot;">​</a></h4><p>After logging in:</p><ul><li>Navigate to the <strong>Apps</strong> section.</li><li>Under <strong>Individual Access</strong>, click <strong>Create New App/Edit App .</strong></li><li>Click <strong>Submit</strong> to register your app.</li><li>An <strong>API Key</strong> will be created for authenticated API usage</li></ul><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><h4 id="_3-retrieve-api-credentials" tabindex="-1">3. Retrieve API Credentials <a class="header-anchor" href="#_3-retrieve-api-credentials" aria-label="Permalink to &quot;3. Retrieve API Credentials&quot;">​</a></h4><p>After generating the API Key, copy the alphanumeric <strong>API Key</strong> shown for the app. This single value is what Tradeboard needs.</p><p>The individual-access login authenticates with the API key alone: every call sends <code>Bearer &lt;api_key&gt;:&lt;access_token&gt;</code>, and the login endpoint sends <code>Bearer &lt;api_key&gt;</code> on its own. The <strong>api secret</strong> is only used by the third-party OAuth code exchange, which Tradeboard does not use, so you can leave it out.</p><figure><img src="'+d+`" alt=""><figcaption></figcaption></figure><h3 id="configuration" tabindex="-1">Configuration: <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration:&quot;">​</a></h3><p>Here is how you would typically set up your environment variables in a <code>.env</code> file for TradeJini:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;your_tradejini_apikey_here&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">REDIRECT_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/tradejini/callback&#39;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>BROKER_API_KEY</code> must hold the app <strong>API Key</strong>, not your client code. Older Tradeboard builds read the key from <code>BROKER_API_SECRET</code>, so that variable is still accepted as a fallback, but new installs should use <code>BROKER_API_KEY</code>. The two values look identical at rest (both are 32-character alphanumeric strings), so a mix-up shows up only as a bare <code>401 Unauthorized</code> from the login endpoint.</p></div><p>These credentials will be used by Tradeboard to authenticate, fetch session tokens, and access market feeds or place orders.</p><h3 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h3><p>Clicking Connect opens the TradeJini login form, which asks for a password and a 2FA code:</p><ul><li><strong>Password</strong> is your CubePlus login <strong>PIN</strong>, not your account password</li><li><strong>2FA</strong> accepts either <code>totp</code> (authenticator app) or <code>otp</code> (SMS or email)</li></ul><p>A non-whitelisted source IP, a wrong API key, a wrong password and a stale 2FA code all fail with the same bare <code>401 Unauthorized</code>. Individual apps only accept requests from the static IP whitelisted against the app in the developer portal, so check that first.</p><h3 id="integration-benefits" tabindex="-1">Integration Benefits <a class="header-anchor" href="#integration-benefits" aria-label="Permalink to &quot;Integration Benefits&quot;">​</a></h3><p>Integrating with the TradeJini API via Tradeboard opens up a world of possibilities for algorithmic trading and real-time data access. The CubePlus API offers:</p><ul><li>High-performance WebSocket feed for LTP, OHLC, depth, and indices.</li><li>REST API endpoints for order management and historical data.</li><li>Support for complex order types and multi-segment instruments.</li></ul><p>To ensure a reliable experience with TradeJini’s API:</p><ul><li>Handle rate limits and WebSocket throttling appropriately.</li><li>Store and manage tokens securely.</li><li>Implement robust error handling, retry mechanisms, and logging.</li></ul><p>By following best practices, developers and traders can leverage the TradeJini infrastructure to build high-frequency, data-driven strategies with confidence.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/tradejini/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,34)])])}const _=a(c,[["render",p]]);export{m as __pageData,_ as default};
